"/><text x=\"705\" y=\"360\" font-size=\"30\" fill=\"#f59e0b\" text-anchor=\"middle\" font-family=\"Arial\">G</text><text x=\"705\" y=\"400\" font-size=\"17\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">gravity's</text><text x=\"705\" y=\"428\" font-size=\"17\" fill=\"#888\" text-anchor=\"middle\" font-family=\"Arial\">strength</text><rect x=\"840\" y=\"310\" width=\"170\" height=\"150\" rx=\"12\" fill=\"rgba(236,72,153,0.14)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"925\" y=\"360\" font-size=\"30\" fill=\"#ec4899\" text-anchor=\"middle\" font-family=\"Arial\">k</text><text x=\"925\" y=\"400\" font-size=\"17\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">curvature</text><text x=\"925\" y=\"428\" font-size=\"17\" fill=\"#888\" text-anchor=\"middle\" font-family=\"Arial\">of space</text><rect x=\"180\" y=\"520\" width=\"740\" height=\"180\" rx=\"14\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"3\"/><text x=\"550\" y=\"580\" font-size=\"24\" fill=\"#ef4444\" text-anchor=\"middle\" font-family=\"Arial\">There is NO static solution</text><text x=\"550\" y=\"630\" font-size=\"21\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">a must change with time</text><text x=\"550\" y=\"672\" font-size=\"20\" fill=\"#888\" text-anchor=\"middle\" font-family=\"Arial\">so the universe expands or contracts</text><rect x=\"250\" y=\"750\" width=\"260\" height=\"180\" rx=\"14\" fill=\"rgba(59,130,246,0.12)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"380\" y=\"805\" font-size=\"21\" fill=\"#3b82f6\" text-anchor=\"middle\" font-family=\"Arial\">EXPAND</text><circle cx=\"380\" cy=\"865\" r=\"20\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"2\"/><path d=\"M410 865 L470 865\" stroke=\"#3b82f6\" stroke-width=\"3\"/><polygon points=\"470,855 490,865 470,875\" fill=\"#3b82f6\"/><rect x=\"590\" y=\"750\" width=\"260\" height=\"180\" rx=\"14\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"720\" y=\"805\" font-size=\"21\" fill=\"#f59e0b\" text-anchor=\"middle\" font-family=\"Arial\">CONTRACT</text><circle cx=\"720\" cy=\"865\" r=\"20\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"2\"/><path d=\"M690 865 L630 865\" stroke=\"#f59e0b\" stroke-width=\"3\"/><polygon points=\"630,855 610,865 630,875\" fill=\"#f59e0b\"/></svg>",
